from .money import MAX_AMOUNT_CENTS, cents_to_amount, format_amount, parse_cents


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")
    # Each item goes through the same validation as parse_amount; summing
    # integer cents keeps the total exact regardless of decimal precision.
    total = 0
    for item in amounts:
        total += parse_cents(item)
    if total > MAX_AMOUNT_CENTS:
        raise ValueError("total must be at most 1000000.00")
    return {"total": format_amount(cents_to_amount(total)), "count": len(amounts)}

